sparql:
PREFIX Watson: <http://watson.local/pharma#>
PREFIX rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?document ?title ?expires ?sensitivity
WHERE {
  ?document Watson:lifecycleState "ACTIVE" ;
            Watson:documentTitle ?title ;
            Watson:expiry_date ?expires ;
            Watson:sensitivityLevel ?sensitivity .
  FILTER (?expires >= "2026-10-28"^^xsd:date && ?expires <= "2027-01-26"^^xsd:date)
}
ORDER BY ?expires
